import {
  AllTrainingsCard,
  CardsContainer,
  Empty,
  TrainingCard,
} from '../../components';
import { pillarStyles } from '../../constants';
import { Training, TrainingHubData } from '../../domain';
import { StyledPillarView } from './PillarView.styles';

export const PillarView = ({ data }: { data: TrainingHubData }) => {
  const pillars = Object.keys(data);

  const cardsToShow = 4;

  return (
    <StyledPillarView>
      {pillars.map((pillar) => (
        <CardsContainer
          key={pillar}
          icon={pillarStyles[pillar].icon}
          variant={pillar}
          title={data[pillar].name}
          titleSize="lg"
        >
          {data[pillar].trainings.length === 0 ? (
            <Empty
              type="coming-soon"
              title="Coming soon!"
              description="Training for this pillar will soon be created and added!"
            />
          ) : (
            <>
              {data[pillar].trainings
                .slice(0, cardsToShow)
                .map((training: Training) => (
                  <TrainingCard
                    pillarId={data[pillar].id}
                    key={training.id}
                    training={training}
                  />
                ))}
              {data[pillar].trainings.length > cardsToShow && (
                <AllTrainingsCard
                  trainings={data[pillar].trainings}
                  pillarId={data[pillar].id}
                />
              )}
            </>
          )}
        </CardsContainer>
      ))}
    </StyledPillarView>
  );
};
